        methods:{
            async sign(){
                document.getElementById('btn').disabled=true
                if(this.information.password != this.information.c_password){
                    alert('verifier votre mot de passe')
                }else{
                    this.loading = !this.loading
                    await this.axios.post(this.localhost+'register',this.information)
                    .then((response)=>{
                        console.log(response.data)
                        document.getElementById('btn').disabled=false
                        this.loading = !this.loading
                        this.$router.push('/login')
                    })
                    .catch((e)=>{console.log(e);
                    })

                }
            },
            verification_mdp(){
                if(1 < this.information.password.length && this.information.password.length < 8){
                    this.longueur_pass = false
                    document.getElementById('btn').disabled=true
                }else{
                    this.longueur_pass = true
                    document.getElementById('btn').disabled=false
                }
            },
            verification_cmdp(){
                if(this.information.password != this.information.c_password){
                    this.c_pass = false
                    document.getElementById('btn').disabled=true
                }else{
                    this.c_pass = true
                    document.getElementById('btn').disabled=false
                }
            }
        }
