import { createRouter, createWebHistory  } from 'vue-router'
import acceuil from '../components/pages/acceuil/AcceuilComponent.vue'
import navbaracceuil from '../components/pages/navbar/NavabaracceuilComponent.vue'
import login from '../components/pages/login/LoginComponent.vue'
import sigin from '../components/pages/login/SiginComponent.vue'
import navbar from '../components/pages/navbar/NavbarComponent.vue'

const router = createRouter({
  history: createWebHistory (),
  routes : [
    {
      path: '/',
      name: 'home',
      component: navbaracceuil,
      children : [
        {
          path : '',
          components : {
            default : navbaracceuil,
            one:acceuil
          }
          
        }
      ]
    },
    {
      path : '/acceuil',
      name: 'acceuil',
      component : navbar
    },
    {
      path:'/login',
      name: 'login',
      component : login
    },
    {
      path: '/sigin',
      name : 'sigin',
      component: sigin
    },
    {
      path:'/:pathMatch(.*)*',
      redirect : "/"
    }
  
  ]
})

export default router
