<template>
    <div class="bg-cover bg-center t">
        <div class="w-full h-screen px-2 bg-black bg-opacity-50 flex justify-center items-center">
            <div class="w-[100%] md:w-[95%] lg:w-[80%] border-2 border-[#dfbf98] md:h-[90%] flex justiy-center items-center lg:mt-0 h-[60%] lg:h-[90%] overflow-hidden rounded-xl">
                <div class="w-[50%] lg:w-[55%] hidden md:block h-full relative overflow-hidden">
                    <div class="absolute w-full h-full p-6 flex justify-end flex-col bg-black bg-opacity-50">
                        <p class="text-white text-[20px] lg:text-[30px] font-bold">
                            C'est un bohneur de vous revoir parmis nous pour ravivez vos papilles
                        </p>
                    </div>
                    <img src="../../../assets/images/pexels-rajesh-tp-749235-1633525.jpg" class="w-full h-full object-cover object-center" alt="">
                </div>
                <div class="w-[100%] relative md:w-[50%] lg:w-[45%] p-6 gap-4 md:gap-2 lg:gap-4 flex flex-col justify-center text-white items-center h-full overflow-hidden">
                    <div :class="connexion_echoue ? 'translate-x-[0%]':'translate-x-[100%]'" class="absolute bg-red-500 top-2 right-0 text-[18px] duration-300 transform  text-white font-semibold px-4 py-2 ">
                        Veuillez verifier votre email ou mot de passe
                    </div>
                    <div :class="connexion_reussir ? 'translate-x-[0%]':'translate-x-[100%]'" class="absolute bg-green-500 top-2 right-0 text-[18px] duration-300 transform translate-x-[100%] text-white font-semibold px-4 py-2 ">
                        Connection reussir
                    </div>
                    <div class="w-full md:h-[3rem] lg:h-[5rem] h-[5rem]">
                        <router-link to="/"><img src="../../../assets/logo.jpg" class="object-contain object-center h-full" alt=""></router-link>
                    </div>
                    <div class="flex flex-col w-full md:h-full md:gap-2 lg:gap-4 gap-4 justify-center">
                        <p class=" flex flex-col w-full items-center ">
                            <span class="text-[2rem] lg:text-[3rem] font-bold">Connexion</span>
                            <span classe="text-[14px] lg:text-[14px] text-center">Entrez votre email et votre mot de passe</span>
                        </p>
                        <form @submit.prevent="test" class="w-full h-fit flex flex-col gap-4">
                            <div class="w-full flex flex-col gap-2">
                                <label for="mail">Email</label>
                                <input required v-model="information.email" type="email" name="mail" class="w-full rounded-lg outline-none border-2 text-[16px]  lg:text-[18px]  focus:border-[#dfbf98] px-2 py-1 text-gray-800 font-semibold" id="mail">
                            </div>
                            <div class="w-full flex flex-col gap-2 relative">
                                <label for="pass" class="flex w-full justify-between items-end">
                                    <span class="text-[16px]">Mot de passe</span>
                                    <span @click="mdp = !mdp" class="duration-300 text-[14px] cursor-pointer hover:text-[#dfbf98]">afficher mot de passe</span>
                                </label>
                                <input @keyup="verification_mdp()"  required v-model="information.password" :type="mdp ? 'password':'text'" name="password" class="w-full rounded-lg z-[6] outline-none  text-[16px]  lg:text-[18px] border-2 focus:border-[#dfbf98] px-2 py-1 text-gray-800 font-semibold" id="pass">
                                <p :class="longueur_pass ? 'translate-y-[0%]':'translate-y-[100%]'" class="absolute text-[10px] font-semibold p-1 right-0 mr-1 mb-1  bg-[#8f2500] text-white duration-300 bottom-0 transfrom  z-[5]">le mot de passe doit depasser au moins 8 lettre</p>
                            </div>
                            <button :disabled="!longueur_pass" :class="loading ? 'bg-transparent':''" class="mx-auto mt-2 justify-center items-center flex py-1 rounded-lg w-[8rem] bg-[#dfbf98] duration-300 font-semibold text-white hover:bg-transparent hover:text-[#dfbf98] border-2 border-[#dfbf98] ">
                                <p v-if="loading == false">Se connecter</p>
                                <p v-else class="w-7 h-7 rounded-full border-2 border-t-[#dfbf98] animate-spin"></p>
                            </button>
                        </form>
                        <div class="flex justify-between w-full">
                            <p class="text-[13px] md:text-[14px] ">
                                <router-link  to="/" class="duration-300 hover:text-[#dfbf98]">mot de passe oublié</router-link>
                            </p>
                            <p class="text-[13px] md:text-[14px] ">
                                Vous n'avez pas de compte <router-link  to="/sigin" class="duration-300 hover:text-[#dfbf98]">cliquer ici</router-link>
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
    export default {
        data (){
            return{
                mdp : true,
                information : {
                    email: '',
                    password:''
                },
                loading:false,
                localhost: this.$store.state.localhost,
                connexion_echoue:false,
                connexion_reussir:false,
                longueur_pass:true
            }
        },
        methods: {
            test(){
                this.loading = !this.loading
                this.axios.post(this.localhost+'login',this.information)
                .then((response)=>{
                    console.log(response.data)
                    this.loading = false
                    this.connexion_reussir = true
                    localStorage.setItem('Token',response.data.token)
                    setTimeout(()=>{
                        this.connexion_reussir = false
                        this.$router.push('/acceuil')
                    },1500)
                })
                .catch((e)=>{
                    console.log(e)
                    this.loading = false
                    this.connexion_echoue = true
                    setTimeout(()=>{
                        this.connexion_echoue = false
                    },5000)
                })
                // this.$router.push('acceuil')
            },
            verification_mdp(){
                if(1 < this.information.password.length && this.information.password.length < 8){
                    this.longueur_pass = false
                }else{
                    this.longueur_pass = true
                }
            },
        }
    }
</script>

<style>
    .t{
        background-image: url('../../../assets/images/wallpaperflare.com_wallpaper.jpg');
    }
